window.ISMBusinessPodcasts=[{"id":"idioms-to-clear-actions","title":"Reuniões: expressões que viram ações claras","lesson":"business-practice.html#idioms-to-clear-actions/0","image":"assets/reference-meeting-language.svg","versions":{"pt":{"label":"Português + exemplos em inglês","chapters":[{"id":"opening","title":"Comece pelo contexto","segments":[{"lang":"pt-BR","text":"Bem-vindo a uma aula em áudio do ISM Business. Este episódio usa situações profissionais fictícias. Na primeira vez, acompanhe o sentido. Depois retorne aos capítulos e pratique em voz alta. Pause sempre que precisar de mais tempo. A narração é sintetizada. Os personagens usam uma voz inglesa com pequenas variações de ritmo e tom.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":0.0,"end":32.656},{"lang":"pt-BR","text":"Conheça a situação que vamos praticar.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":33.156,"end":37.22},{"lang":"en-US","text":"A new colleague joins your project team. Explain useful meeting expressions, check understanding and agree on a clear written action.","pauseMs":1300,"rate":92,"role":"narrator","pitch":0,"start":37.72,"end":46.563},{"lang":"pt-BR","text":"Ao final, explique uma expressão útil, participe da conversa e deixe claro um próximo passo. Você não precisa decorar todas as frases. O objetivo é comunicar a mensagem com suas próprias palavras.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":47.863,"end":66.885}],"start":0.0,"end":67.385},{"id":"vocabulary","title":"Vocabulário explicado","segments":[{"lang":"pt-BR","text":"Vamos trabalhar doze expressões úteis. Para cada uma, ouça o termo, compreenda o sentido e acompanhe uma frase de exemplo. Use a pausa depois do exemplo para repetir ou criar uma frase semelhante.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":67.385,"end":85.901},{"lang":"en-US","text":"get the ball rolling.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":86.401,"end":88.285},{"lang":"pt-BR","text":"dar início.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":88.585,"end":90.476},{"lang":"en-US","text":"We can get the ball rolling with a short update.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":90.976,"end":94.13},{"lang":"en-US","text":"fill me in.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":95.83,"end":97.39},{"lang":"pt-BR","text":"atualizar-me sobre o assunto.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":97.69,"end":100.922},{"lang":"en-US","text":"Could you fill me in after the call?","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":101.422,"end":103.951},{"lang":"en-US","text":"sharp.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":105.651,"end":106.986},{"lang":"pt-BR","text":"em ponto.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":107.286,"end":109.073},{"lang":"en-US","text":"The call starts at nine sharp.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":109.573,"end":112.167},{"lang":"en-US","text":"touch base.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":113.867,"end":115.421},{"lang":"pt-BR","text":"fazer um contato breve para alinhar.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":115.721,"end":119.527},{"lang":"en-US","text":"We can touch base on Wednesday.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":120.027,"end":122.436},{"lang":"en-US","text":"on the same page.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":124.136,"end":126.015},{"lang":"pt-BR","text":"com o mesmo entendimento.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":126.315,"end":129.188},{"lang":"en-US","text":"Let us check that we are on the same page.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":129.688,"end":132.702},{"lang":"en-US","text":"take the lead.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":134.402,"end":135.956},{"lang":"pt-BR","text":"assumir a coordenação.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":136.256,"end":138.957},{"lang":"en-US","text":"I can take the lead on the summary.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":139.457,"end":141.956},{"lang":"en-US","text":"keep me posted.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":143.656,"end":145.435},{"lang":"pt-BR","text":"mantenha-me informado.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":145.735,"end":148.349},{"lang":"en-US","text":"Please keep me posted about the reply.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":148.849,"end":151.718},{"lang":"en-US","text":"put it in writing.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":153.418,"end":155.138},{"lang":"pt-BR","text":"registrar por escrito.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":155.438,"end":158.282},{"lang":"en-US","text":"We should put it in writing today.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":158.782,"end":161.152},{"lang":"en-US","text":"plain English.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":162.852,"end":164.566},{"lang":"pt-BR","text":"inglês claro e direto.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":164.866,"end":167.783},{"lang":"en-US","text":"Please explain the decision in plain English.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":168.283,"end":171.462},{"lang":"en-US","text":"idiom.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":173.162,"end":174.506},{"lang":"pt-BR","text":"expressão idiomática.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":174.806,"end":177.45},{"lang":"en-US","text":"This idiom may be unfamiliar to a new colleague.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":177.95,"end":181.139},{"lang":"en-US","text":"next step.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":182.839,"end":184.453},{"lang":"pt-BR","text":"próximo passo.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":184.753,"end":187.031},{"lang":"en-US","text":"Our next step is to draft a short summary.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":187.531,"end":190.675},{"lang":"en-US","text":"get the show on the road.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":192.375,"end":194.419},{"lang":"pt-BR","text":"colocar o plano em execução.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":194.719,"end":197.954},{"lang":"en-US","text":"We can get the show on the road after approval.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":198.454,"end":201.608}],"start":67.385,"end":203.308},{"id":"pronunciation","title":"Pronúncia e repetição","segments":[{"lang":"pt-BR","text":"Agora vamos observar a pronúncia. Os exemplos são modelos falados, não uma avaliação da sua fala. Ouça a parte mais forte e como as palavras se ligam. Repita com calma e depois diga a expressão como um grupo.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":203.308,"end":223.243},{"lang":"pt-BR","text":"Ouça as três palavras como um grupo curto. Mantenha o som final da primeira palavra e ligue a expressão, sem acrescentar uma vogal. O sentido é atualizar alguém sobre um assunto.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":223.743,"end":240.154},{"lang":"en-US","text":"fill me in.","pauseMs":1800,"rate":78,"role":"narrator","pitch":0,"start":240.654,"end":242.214},{"lang":"en-US","text":"fill me in.","pauseMs":1800,"rate":98,"role":"narrator","pitch":0,"start":244.014,"end":245.573},{"lang":"pt-BR","text":"Dê destaque às palavras que expressam mesmo e página. Nesta conversa, a expressão fala de entendimento comum, não de uma página física.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":247.373,"end":260.287},{"lang":"en-US","text":"on the same page.","pauseMs":1800,"rate":78,"role":"narrator","pitch":0,"start":260.787,"end":262.666},{"lang":"en-US","text":"on the same page.","pauseMs":1800,"rate":98,"role":"narrator","pitch":0,"start":264.466,"end":266.345},{"lang":"pt-BR","text":"Ouça o final da primeira palavra e o início da segunda. A expressão destaca o horário exato. Repita o grupo e depois acrescente a referência de fuso.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":268.145,"end":282.496},{"lang":"en-US","text":"nine sharp.","pauseMs":1800,"rate":78,"role":"narrator","pitch":0,"start":282.996,"end":284.64},{"lang":"en-US","text":"nine sharp.","pauseMs":1800,"rate":98,"role":"narrator","pitch":0,"start":286.44,"end":288.084}],"start":203.308,"end":289.884},{"id":"dialogue","title":"Diálogo profissional","segments":[{"lang":"pt-BR","text":"Ouça a conversa completa. Observe o pedido, o esclarecimento e o compromisso final. Cada papel mantém o mesmo padrão de voz durante o diálogo. Depois, consulte a transcrição se precisar de apoio.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":289.884,"end":309.487},{"lang":"en-US","text":"We can get the ball rolling with a short update. Welcome to the project, Riley.","pauseMs":400,"rate":94,"role":"Morgan","pitch":-1,"start":309.987,"end":315.985},{"lang":"en-US","text":"Thanks. Could you fill me in on the decision from yesterday?","pauseMs":400,"rate":90,"role":"Riley","pitch":2,"start":316.385,"end":321.164},{"lang":"en-US","text":"We agreed to draft a one-page summary. Tomorrow’s call starts at nine sharp, London time.","pauseMs":400,"rate":94,"role":"Morgan","pitch":-1,"start":321.564,"end":328.612},{"lang":"en-US","text":"Understood. Can we touch base on Wednesday to check the response?","pauseMs":400,"rate":90,"role":"Riley","pitch":2,"start":329.012,"end":334.281},{"lang":"en-US","text":"Yes. First, let us check that we are on the same page about the summary.","pauseMs":400,"rate":94,"role":"Morgan","pitch":-1,"start":334.681,"end":340.61},{"lang":"en-US","text":"I can take the lead on the first draft and send it today.","pauseMs":400,"rate":90,"role":"Riley","pitch":2,"start":341.01,"end":344.658},{"lang":"en-US","text":"Great. Please keep me posted if any information is missing.","pauseMs":400,"rate":94,"role":"Morgan","pitch":-1,"start":345.058,"end":350.017},{"lang":"en-US","text":"I will put it in writing so the team can check the owner and deadline.","pauseMs":400,"rate":90,"role":"Riley","pitch":2,"start":350.417,"end":354.651},{"lang":"en-US","text":"Please use plain English. Some colleagues are new to this project.","pauseMs":400,"rate":94,"role":"Morgan","pitch":-1,"start":355.051,"end":360.175},{"lang":"en-US","text":"Of course. If an idiom causes confusion, I will explain it another way.","pauseMs":400,"rate":90,"role":"Riley","pitch":2,"start":360.575,"end":366.468},{"lang":"en-US","text":"Our next step is your draft today, followed by my review tomorrow.","pauseMs":400,"rate":94,"role":"Morgan","pitch":-1,"start":366.868,"end":371.647},{"lang":"en-US","text":"Then we can get the show on the road after your approval. I will send the summary today.","pauseMs":400,"rate":90,"role":"Riley","pitch":2,"start":372.047,"end":377.94},{"lang":"pt-BR","text":"Em outra escuta, assuma um dos papéis. Pause antes da fala desse personagem e tente responder. Uma resposta diferente também pode ser adequada quando comunica o mesmo objetivo com clareza.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":378.34,"end":396.17}],"start":289.884,"end":396.67},{"id":"practice","title":"Sua vez de responder","segments":[{"lang":"pt-BR","text":"Agora é sua vez. Você ouvirá quatro perguntas. Depois de cada uma haverá uma pausa curta para responder e, em seguida, um modelo possível. Pause o player se precisar de mais tempo. O modelo não é a única resposta correta.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":396.67,"end":418.982},{"lang":"en-US","text":"What does get the ball rolling mean here?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"start":419.482,"end":422.286},{"lang":"pt-BR","text":"Uma resposta possível é:","pauseMs":200,"rate":98,"role":"narrator","pitch":0,"start":426.786,"end":429.847},{"lang":"en-US","text":"It means start the discussion with a short update.","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"start":430.047,"end":433.31},{"lang":"en-US","text":"Could you confirm the call time?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"start":434.91,"end":437.344},{"lang":"pt-BR","text":"Uma resposta possível é:","pauseMs":200,"rate":98,"role":"narrator","pitch":0,"start":441.844,"end":444.904},{"lang":"en-US","text":"The call is tomorrow at nine, London time.","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"start":445.104,"end":448.674},{"lang":"en-US","text":"Who will take the lead on the summary?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"start":450.274,"end":452.803},{"lang":"pt-BR","text":"Uma resposta possível é:","pauseMs":200,"rate":98,"role":"narrator","pitch":0,"start":457.303,"end":460.363},{"lang":"en-US","text":"I will draft the summary today, and Morgan will review it tomorrow.","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"start":460.563,"end":465.001},{"lang":"en-US","text":"How will you avoid confusion?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"start":466.601,"end":468.99},{"lang":"pt-BR","text":"Uma resposta possível é:","pauseMs":200,"rate":98,"role":"narrator","pitch":0,"start":473.49,"end":476.55},{"lang":"en-US","text":"I will use plain English and put the next step in writing.","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"start":476.75,"end":480.514}],"start":396.67,"end":482.114},{"id":"summary","title":"Resumo e aplicação","segments":[{"lang":"pt-BR","text":"Para concluir, escolha três expressões do episódio e use-as em uma mensagem curta. Confira o objetivo, o responsável e o próximo passo. Separe fatos observados de previsões. Volte à aula para fazer os jogos, os exercícios de gramática e a revisão.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":482.114,"end":506.677},{"lang":"pt-BR","text":"Esta é uma atividade de prática. A escuta e a autoavaliação não certificam pronúncia ou proficiência. Peça feedback ao professor e repita um capítulo buscando uma melhoria específica. Obrigado por estudar com o ISM Business.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":507.177,"end":528.532}],"start":482.114,"end":529.032}],"audio":"assets/podcasts/idioms-to-clear-actions-pt.mp3","duration":529.032,"bytes":4233133,"sha256":"feaef771b130d6b3360d30cb47b8b80867067aaf97ee3ce3371dceed8e2bcb0d"},"en":{"label":"English only","chapters":[{"id":"opening","title":"Start with the situation","segments":[{"lang":"en-US","text":"Welcome to an I S M Business audio lesson. This episode uses fictional workplace situations. Listen once for meaning, then return to a chapter and practise aloud. You can pause whenever you need more thinking time. This is synthetic narration, with a single English voice using small delivery variations for the two dialogue roles.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":0.0,"end":22.605},{"lang":"en-US","text":"Here is your situation.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":23.105,"end":25.32},{"lang":"en-US","text":"A new colleague joins your project team. Explain useful meeting expressions, check understanding and agree on a clear written action.","pauseMs":1300,"rate":92,"role":"narrator","pitch":0,"start":25.82,"end":34.662},{"lang":"en-US","text":"At the end, explain one useful expression, take part in the conversation, and make a clear next step. You do not need to memorize every sentence. Aim to communicate the message in your own words.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":35.962,"end":49.99}],"start":0.0,"end":50.49},{"id":"vocabulary","title":"Vocabulary explained","segments":[{"lang":"en-US","text":"We will build twelve useful expressions. For each one, listen to the expression, understand the meaning, and hear an example. Use the pause after each example to repeat or create a similar sentence.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":50.49,"end":64.382},{"lang":"en-US","text":"get the ball rolling.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":64.882,"end":66.766},{"lang":"en-US","text":"Start an activity or discussion.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":67.066,"end":69.765},{"lang":"en-US","text":"We can get the ball rolling with a short update.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":70.265,"end":73.419},{"lang":"en-US","text":"fill me in.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":75.119,"end":76.678},{"lang":"en-US","text":"Give me the information I have missed.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":76.978,"end":79.687},{"lang":"en-US","text":"Could you fill me in after the call?","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":80.187,"end":82.716},{"lang":"en-US","text":"sharp.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":84.416,"end":85.75},{"lang":"en-US","text":"Exactly at the stated time.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":86.05,"end":88.504},{"lang":"en-US","text":"The call starts at nine sharp.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":89.004,"end":91.599},{"lang":"en-US","text":"touch base.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":93.299,"end":94.853},{"lang":"en-US","text":"Have a brief conversation to check progress.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":95.153,"end":98.447},{"lang":"en-US","text":"We can touch base on Wednesday.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":98.947,"end":101.356},{"lang":"en-US","text":"on the same page.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":103.056,"end":104.935},{"lang":"en-US","text":"Share an understanding of the situation.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":105.235,"end":108.274},{"lang":"en-US","text":"Let us check that we are on the same page.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":108.774,"end":111.788},{"lang":"en-US","text":"take the lead.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":113.488,"end":115.042},{"lang":"en-US","text":"Be the person coordinating an activity.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":115.342,"end":118.341},{"lang":"en-US","text":"I can take the lead on the summary.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":118.841,"end":121.34},{"lang":"en-US","text":"keep me posted.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":123.04,"end":124.819},{"lang":"en-US","text":"Continue to give me updates.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":125.119,"end":127.589},{"lang":"en-US","text":"Please keep me posted about the reply.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":128.089,"end":130.958},{"lang":"en-US","text":"put it in writing.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":132.658,"end":134.377},{"lang":"en-US","text":"Make a written record of an agreement.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":134.677,"end":137.191},{"lang":"en-US","text":"We should put it in writing today.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":137.691,"end":140.06},{"lang":"en-US","text":"plain English.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":141.76,"end":143.474},{"lang":"en-US","text":"Clear language that people can understand.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":143.774,"end":146.898},{"lang":"en-US","text":"Please explain the decision in plain English.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":147.398,"end":150.577},{"lang":"en-US","text":"idiom.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":152.277,"end":153.621},{"lang":"en-US","text":"An expression whose meaning is not simply its separate words.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":153.921,"end":157.915},{"lang":"en-US","text":"This idiom may be unfamiliar to a new colleague.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":158.415,"end":161.604},{"lang":"en-US","text":"next step.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":163.304,"end":164.918},{"lang":"en-US","text":"The action that follows the current one.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":165.218,"end":167.987},{"lang":"en-US","text":"Our next step is to draft a short summary.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":168.487,"end":171.631},{"lang":"en-US","text":"get the show on the road.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":173.331,"end":175.375},{"lang":"en-US","text":"Start carrying out a plan that is ready.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":175.675,"end":178.604},{"lang":"en-US","text":"We can get the show on the road after approval.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":179.104,"end":182.258}],"start":50.49,"end":183.958},{"id":"pronunciation","title":"Pronunciation and repetition","segments":[{"lang":"en-US","text":"Now focus on pronunciation. The examples are spoken models, not a pronunciation score. Listen for the stronger beat and how words join in a phrase. Repeat slowly, then say the whole phrase naturally.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":183.958,"end":199.05},{"lang":"en-US","text":"Listen to the three words as one short group. Keep the final sound of fill and connect it to me. There is no need to translate each word separately.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":199.55,"end":209.528},{"lang":"en-US","text":"fill me in.","pauseMs":1800,"rate":78,"role":"narrator","pitch":0,"start":210.028,"end":211.587},{"lang":"en-US","text":"fill me in.","pauseMs":1800,"rate":98,"role":"narrator","pitch":0,"start":213.387,"end":214.946},{"lang":"en-US","text":"Make same and page easy to hear. The expression is about shared understanding, not a physical page in this conversation.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":216.746,"end":225.134},{"lang":"en-US","text":"on the same page.","pauseMs":1800,"rate":78,"role":"narrator","pitch":0,"start":225.634,"end":227.514},{"lang":"en-US","text":"on the same page.","pauseMs":1800,"rate":98,"role":"narrator","pitch":0,"start":229.314,"end":231.193},{"lang":"en-US","text":"Hear the final sound in nine and the beginning of sharp. Sharp makes the exact time important. Repeat the whole group, then add London time.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":232.993,"end":243.071},{"lang":"en-US","text":"nine sharp.","pauseMs":1800,"rate":78,"role":"narrator","pitch":0,"start":243.571,"end":245.215},{"lang":"en-US","text":"nine sharp.","pauseMs":1800,"rate":98,"role":"narrator","pitch":0,"start":247.015,"end":248.659}],"start":183.958,"end":250.459},{"id":"dialogue","title":"Workplace dialogue","segments":[{"lang":"en-US","text":"Listen to the complete conversation. Notice the request, the clarification and the final commitment. The two roles keep the same delivery throughout. Read the transcript afterwards if you need support.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":250.459,"end":264.276},{"lang":"en-US","text":"We can get the ball rolling with a short update. Welcome to the project, Riley.","pauseMs":400,"rate":94,"role":"Morgan","pitch":-1,"start":264.776,"end":270.775},{"lang":"en-US","text":"Thanks. Could you fill me in on the decision from yesterday?","pauseMs":400,"rate":90,"role":"Riley","pitch":2,"start":271.175,"end":275.954},{"lang":"en-US","text":"We agreed to draft a one-page summary. Tomorrow’s call starts at nine sharp, London time.","pauseMs":400,"rate":94,"role":"Morgan","pitch":-1,"start":276.354,"end":283.402},{"lang":"en-US","text":"Understood. Can we touch base on Wednesday to check the response?","pauseMs":400,"rate":90,"role":"Riley","pitch":2,"start":283.802,"end":289.07},{"lang":"en-US","text":"Yes. First, let us check that we are on the same page about the summary.","pauseMs":400,"rate":94,"role":"Morgan","pitch":-1,"start":289.47,"end":295.399},{"lang":"en-US","text":"I can take the lead on the first draft and send it today.","pauseMs":400,"rate":90,"role":"Riley","pitch":2,"start":295.799,"end":299.448},{"lang":"en-US","text":"Great. Please keep me posted if any information is missing.","pauseMs":400,"rate":94,"role":"Morgan","pitch":-1,"start":299.848,"end":304.807},{"lang":"en-US","text":"I will put it in writing so the team can check the owner and deadline.","pauseMs":400,"rate":90,"role":"Riley","pitch":2,"start":305.207,"end":309.44},{"lang":"en-US","text":"Please use plain English. Some colleagues are new to this project.","pauseMs":400,"rate":94,"role":"Morgan","pitch":-1,"start":309.84,"end":314.964},{"lang":"en-US","text":"Of course. If an idiom causes confusion, I will explain it another way.","pauseMs":400,"rate":90,"role":"Riley","pitch":2,"start":315.364,"end":321.258},{"lang":"en-US","text":"Our next step is your draft today, followed by my review tomorrow.","pauseMs":400,"rate":94,"role":"Morgan","pitch":-1,"start":321.658,"end":326.436},{"lang":"en-US","text":"Then we can get the show on the road after your approval. I will send the summary today.","pauseMs":400,"rate":90,"role":"Riley","pitch":2,"start":326.836,"end":332.729},{"lang":"en-US","text":"Listen again later and take one role. Pause before that person speaks and predict the response. A different answer can still be appropriate if it communicates the same goal clearly.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":333.129,"end":344.961}],"start":250.459,"end":345.461},{"id":"practice","title":"Your turn to respond","segments":[{"lang":"en-US","text":"Your turn. You will hear four prompts. After each prompt there is a short pause for your response, followed by one possible model. Pause the player if you need more time. The model is not the only correct answer.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":345.461,"end":361.198},{"lang":"en-US","text":"What does get the ball rolling mean here?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"start":361.698,"end":364.502},{"lang":"en-US","text":"One possible response is:","pauseMs":200,"rate":94,"role":"narrator","pitch":0,"start":369.002,"end":371.526},{"lang":"en-US","text":"It means start the discussion with a short update.","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"start":371.726,"end":374.99},{"lang":"en-US","text":"Could you confirm the call time?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"start":376.59,"end":379.024},{"lang":"en-US","text":"One possible response is:","pauseMs":200,"rate":94,"role":"narrator","pitch":0,"start":383.524,"end":386.048},{"lang":"en-US","text":"The call is tomorrow at nine, London time.","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"start":386.248,"end":389.817},{"lang":"en-US","text":"Who will take the lead on the summary?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"start":391.417,"end":393.947},{"lang":"en-US","text":"One possible response is:","pauseMs":200,"rate":94,"role":"narrator","pitch":0,"start":398.447,"end":400.971},{"lang":"en-US","text":"I will draft the summary today, and Morgan will review it tomorrow.","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"start":401.171,"end":405.609},{"lang":"en-US","text":"How will you avoid confusion?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"start":407.209,"end":409.598},{"lang":"en-US","text":"One possible response is:","pauseMs":200,"rate":94,"role":"narrator","pitch":0,"start":414.098,"end":416.622},{"lang":"en-US","text":"I will use plain English and put the next step in writing.","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"start":416.822,"end":420.586}],"start":345.461,"end":422.186},{"id":"summary","title":"Recap and application","segments":[{"lang":"en-US","text":"To recap, choose three expressions from the episode and use them in a short message. Check the goal, the person responsible and the next step. Keep observed facts separate from predictions. Return to the lesson for the games, grammar practice and final review.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":422.186,"end":440.062},{"lang":"en-US","text":"This is a practice activity. Listening and self-assessment do not certify pronunciation or proficiency. Ask your teacher for feedback and repeat one chapter with a specific improvement in mind. Thank you for studying with I S M Business.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":440.562,"end":456.744}],"start":422.186,"end":457.244}],"audio":"assets/podcasts/idioms-to-clear-actions-en.mp3","duration":457.244,"bytes":3658648,"sha256":"d3a119a289bdb8441882f524230b8177a958f21cfaf67d67da2ce2882387e836"}},"disclosure":"Narração sintetizada: Microsoft Maria (português) e Microsoft Zira (inglês). Os personagens compartilham a voz inglesa com variações de ritmo e tom."},{"id":"budget-and-workflow","title":"Operações: explicar orçamento, fluxo e indicadores","lesson":"business-practice.html#budget-and-workflow/0","image":"assets/reference-budget-workflow.svg","versions":{"pt":{"label":"Português + exemplos em inglês","chapters":[{"id":"opening","title":"Comece pelo contexto","segments":[{"lang":"pt-BR","text":"Bem-vindo a uma aula em áudio do ISM Business. Este episódio usa situações profissionais fictícias. Na primeira vez, acompanhe o sentido. Depois retorne aos capítulos e pratique em voz alta. Pause sempre que precisar de mais tempo. A narração é sintetizada. Os personagens usam uma voz inglesa com pequenas variações de ritmo e tom.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":0.0,"end":32.656},{"lang":"pt-BR","text":"Conheça a situação que vamos praticar.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":33.156,"end":37.22},{"lang":"en-US","text":"Your fictional team is reviewing a pilot service. Use the planning figures and process information to propose a small test. No spending decision has been approved.","pauseMs":1300,"rate":92,"role":"narrator","pitch":0,"start":37.72,"end":48.928},{"lang":"pt-BR","text":"Ao final, explique uma expressão útil, participe da conversa e deixe claro um próximo passo. Você não precisa decorar todas as frases. O objetivo é comunicar a mensagem com suas próprias palavras.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":50.228,"end":69.25}],"start":0.0,"end":69.75},{"id":"vocabulary","title":"Vocabulário explicado","segments":[{"lang":"pt-BR","text":"Vamos trabalhar doze expressões úteis. Para cada uma, ouça o termo, compreenda o sentido e acompanhe uma frase de exemplo. Use a pausa depois do exemplo para repetir ou criar uma frase semelhante.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":69.75,"end":88.265},{"lang":"en-US","text":"budget.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":88.765,"end":90.125},{"lang":"pt-BR","text":"orçamento.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":90.425,"end":92.393},{"lang":"en-US","text":"The pilot budget is still a draft.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":92.893,"end":95.592},{"lang":"en-US","text":"cash flow.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":97.292,"end":98.831},{"lang":"pt-BR","text":"fluxo de caixa.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":99.131,"end":101.695},{"lang":"en-US","text":"The cash flow forecast tracks money coming in and going out.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":102.195,"end":106.328},{"lang":"en-US","text":"revenue.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":108.028,"end":109.353},{"lang":"pt-BR","text":"receita.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":109.653,"end":111.507},{"lang":"en-US","text":"Pilot revenue was twenty thousand dollars.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":112.007,"end":115.256},{"lang":"en-US","text":"profit.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":116.956,"end":118.46},{"lang":"pt-BR","text":"lucro.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":118.76,"end":120.322},{"lang":"en-US","text":"Pilot profit was three thousand dollars after recorded costs.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":120.822,"end":125.28},{"lang":"en-US","text":"KPI.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":126.98,"end":128.425},{"lang":"pt-BR","text":"indicador-chave de desempenho.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":128.725,"end":132.196},{"lang":"en-US","text":"Our KPI is the percentage of orders delivered on time.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":132.696,"end":136.67},{"lang":"en-US","text":"workflow.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":138.37,"end":139.899},{"lang":"pt-BR","text":"fluxo de trabalho.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":140.199,"end":142.836},{"lang":"en-US","text":"The workflow has an approval step.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":143.336,"end":145.95},{"lang":"en-US","text":"spreadsheet.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":147.65,"end":149.334},{"lang":"pt-BR","text":"planilha.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":149.634,"end":151.389},{"lang":"en-US","text":"The spreadsheet separates results from estimates.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":151.889,"end":155.358},{"lang":"en-US","text":"outsource.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":157.058,"end":158.687},{"lang":"pt-BR","text":"terceirizar.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":158.987,"end":161.169},{"lang":"en-US","text":"We may outsource a small support task.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":161.669,"end":164.853},{"lang":"en-US","text":"B2B.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":166.553,"end":168.002},{"lang":"pt-BR","text":"entre empresas.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":168.302,"end":170.558},{"lang":"en-US","text":"The B2B service is sold to other companies.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":171.058,"end":174.392},{"lang":"en-US","text":"B2C.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":176.092,"end":177.627},{"lang":"pt-BR","text":"da empresa ao consumidor.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":177.927,"end":180.89},{"lang":"en-US","text":"The B2C service is sold directly to individual customers.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":181.39,"end":185.794},{"lang":"en-US","text":"asset.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":187.494,"end":188.903},{"lang":"pt-BR","text":"ativo; recurso com valor para a organização.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":189.203,"end":193.996},{"lang":"en-US","text":"The server is an asset used by the team.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":194.496,"end":197.465},{"lang":"en-US","text":"target.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":199.165,"end":200.59},{"lang":"pt-BR","text":"meta.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":200.89,"end":202.403},{"lang":"en-US","text":"The target is ninety-five percent on-time delivery.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":202.903,"end":206.512}],"start":69.75,"end":208.212},{"id":"pronunciation","title":"Pronúncia e repetição","segments":[{"lang":"pt-BR","text":"Agora vamos observar a pronúncia. Os exemplos são modelos falados, não uma avaliação da sua fala. Ouça a parte mais forte e como as palavras se ligam. Repita com calma e depois diga a expressão como um grupo.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":208.212,"end":228.147},{"lang":"pt-BR","text":"A parte mais forte da palavra está no início. Preste atenção ao final e evite acrescentar uma vogal depois da última consoante.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":228.647,"end":240.543},{"lang":"en-US","text":"budget.","pauseMs":1800,"rate":78,"role":"narrator","pitch":0,"start":241.043,"end":242.403},{"lang":"en-US","text":"budget.","pauseMs":1800,"rate":98,"role":"narrator","pitch":0,"start":244.203,"end":245.562},{"lang":"pt-BR","text":"As duas palavras têm destaque no início. Além de pronunciar, lembre que receita e lucro são medidas diferentes. Ouça, pause e repita o grupo completo.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":247.362,"end":262.36},{"lang":"en-US","text":"revenue and profit.","pauseMs":1800,"rate":78,"role":"narrator","pitch":0,"start":262.86,"end":264.859},{"lang":"en-US","text":"revenue and profit.","pauseMs":1800,"rate":98,"role":"narrator","pitch":0,"start":266.659,"end":268.659},{"lang":"pt-BR","text":"Diga as letras separadamente em inglês. Depois explique o que está sendo medido. A clareza da explicação é mais importante que o uso da sigla.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":270.459,"end":284.183},{"lang":"en-US","text":"K. P. I..","pauseMs":1800,"rate":78,"role":"narrator","pitch":0,"start":284.683,"end":286.252},{"lang":"en-US","text":"K. P. I..","pauseMs":1800,"rate":98,"role":"narrator","pitch":0,"start":288.052,"end":289.621},{"lang":"en-US","text":"K. P. I. Business to business. Business to consumer.","pauseMs":1800,"rate":94,"role":"narrator","pitch":0,"start":291.421,"end":296.12}],"start":208.212,"end":297.92},{"id":"dialogue","title":"Diálogo profissional","segments":[{"lang":"pt-BR","text":"Ouça a conversa completa. Observe o pedido, o esclarecimento e o compromisso final. Cada papel mantém o mesmo padrão de voz durante o diálogo. Depois, consulte a transcrição se precisar de apoio.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":297.92,"end":317.523},{"lang":"en-US","text":"Let us review the pilot budget. It is still a draft, so no new spending is approved.","pauseMs":400,"rate":94,"role":"Dana","pitch":-1,"start":318.023,"end":324.651},{"lang":"en-US","text":"The spreadsheet separates last month’s results from next month’s estimates.","pauseMs":400,"rate":90,"role":"Sam","pitch":2,"start":325.051,"end":329.905},{"lang":"en-US","text":"What revenue did the pilot generate last month?","pauseMs":400,"rate":94,"role":"Dana","pitch":-1,"start":330.305,"end":333.709},{"lang":"en-US","text":"Revenue was twenty thousand dollars, and profit was three thousand after recorded costs.","pauseMs":400,"rate":90,"role":"Sam","pitch":2,"start":334.109,"end":340.252},{"lang":"en-US","text":"That does not tell us when customers pay. What does the cash flow forecast show?","pauseMs":400,"rate":94,"role":"Dana","pitch":-1,"start":340.652,"end":346.596},{"lang":"en-US","text":"Some payments are expected next month. The cash flow forecast keeps that timing visible.","pauseMs":400,"rate":90,"role":"Sam","pitch":2,"start":346.996,"end":353.654},{"lang":"en-US","text":"Our delivery KPI was ninety percent on time. The target is ninety-five percent.","pauseMs":400,"rate":94,"role":"Dana","pitch":-1,"start":354.054,"end":360.492},{"lang":"en-US","text":"The workflow has a long approval step. We may outsource one small support task as a test.","pauseMs":400,"rate":90,"role":"Sam","pitch":2,"start":360.892,"end":367.636},{"lang":"en-US","text":"Is this for our B2B service, which sells to other companies?","pauseMs":400,"rate":94,"role":"Dana","pitch":-1,"start":368.036,"end":372.634},{"lang":"en-US","text":"Yes. The B2C service for individual customers is outside this pilot.","pauseMs":400,"rate":90,"role":"Sam","pitch":2,"start":373.034,"end":379.013},{"lang":"en-US","text":"The existing server is an asset we can use. Please check the test cost before proposing a purchase.","pauseMs":400,"rate":94,"role":"Dana","pitch":-1,"start":379.413,"end":386.471},{"lang":"en-US","text":"I will send the draft on Thursday, including the KPI, target and approval request.","pauseMs":400,"rate":90,"role":"Sam","pitch":2,"start":386.871,"end":392.98},{"lang":"pt-BR","text":"Em outra escuta, assuma um dos papéis. Pause antes da fala desse personagem e tente responder. Uma resposta diferente também pode ser adequada quando comunica o mesmo objetivo com clareza.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":393.38,"end":411.21}],"start":297.92,"end":411.71},{"id":"practice","title":"Sua vez de responder","segments":[{"lang":"pt-BR","text":"Agora é sua vez. Você ouvirá quatro perguntas. Depois de cada uma haverá uma pausa curta para responder e, em seguida, um modelo possível. Pause o player se precisar de mais tempo. O modelo não é a única resposta correta.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":411.71,"end":434.022},{"lang":"en-US","text":"Are revenue and profit the same here?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"start":434.522,"end":437.321},{"lang":"pt-BR","text":"Uma resposta possível é:","pauseMs":200,"rate":98,"role":"narrator","pitch":0,"start":441.821,"end":444.881},{"lang":"en-US","text":"No. Revenue was twenty thousand dollars, while profit was three thousand after recorded costs.","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"start":445.081,"end":452.519},{"lang":"en-US","text":"What does our KPI measure?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"start":454.119,"end":456.584},{"lang":"pt-BR","text":"Uma resposta possível é:","pauseMs":200,"rate":98,"role":"narrator","pitch":0,"start":461.084,"end":464.144},{"lang":"en-US","text":"It measures the percentage of orders delivered on time. The target is ninety-five percent.","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"start":464.344,"end":470.642},{"lang":"en-US","text":"What change are you proposing?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"start":472.242,"end":474.601},{"lang":"pt-BR","text":"Uma resposta possível é:","pauseMs":200,"rate":98,"role":"narrator","pitch":0,"start":479.101,"end":482.161},{"lang":"en-US","text":"We may outsource a small support task to test a shorter workflow.","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"start":482.361,"end":486.929},{"lang":"en-US","text":"What will you do next?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"start":488.529,"end":490.559},{"lang":"pt-BR","text":"Uma resposta possível é:","pauseMs":200,"rate":98,"role":"narrator","pitch":0,"start":495.059,"end":498.119},{"lang":"en-US","text":"I will send the draft and request approval on Thursday.","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"start":498.319,"end":501.967}],"start":411.71,"end":503.567},{"id":"summary","title":"Resumo e aplicação","segments":[{"lang":"pt-BR","text":"Para concluir, escolha três expressões do episódio e use-as em uma mensagem curta. Confira o objetivo, o responsável e o próximo passo. Separe fatos observados de previsões. Volte à aula para fazer os jogos, os exercícios de gramática e a revisão.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":503.567,"end":528.13},{"lang":"pt-BR","text":"Esta é uma atividade de prática. A escuta e a autoavaliação não certificam pronúncia ou proficiência. Peça feedback ao professor e repita um capítulo buscando uma melhoria específica. Obrigado por estudar com o ISM Business.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":528.63,"end":549.985}],"start":503.567,"end":550.485}],"audio":"assets/podcasts/budget-and-workflow-pt.mp3","duration":550.485,"bytes":4404705,"sha256":"97a88bd9c54d485af443315d9019e6a74efa1cbb7b6e1f3576411df5bd546084"},"en":{"label":"English only","chapters":[{"id":"opening","title":"Start with the situation","segments":[{"lang":"en-US","text":"Welcome to an I S M Business audio lesson. This episode uses fictional workplace situations. Listen once for meaning, then return to a chapter and practise aloud. You can pause whenever you need more thinking time. This is synthetic narration, with a single English voice using small delivery variations for the two dialogue roles.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":0.0,"end":22.605},{"lang":"en-US","text":"Here is your situation.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":23.105,"end":25.32},{"lang":"en-US","text":"Your fictional team is reviewing a pilot service. Use the planning figures and process information to propose a small test. No spending decision has been approved.","pauseMs":1300,"rate":92,"role":"narrator","pitch":0,"start":25.82,"end":37.027},{"lang":"en-US","text":"At the end, explain one useful expression, take part in the conversation, and make a clear next step. You do not need to memorize every sentence. Aim to communicate the message in your own words.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":38.327,"end":52.354}],"start":0.0,"end":52.854},{"id":"vocabulary","title":"Vocabulary explained","segments":[{"lang":"en-US","text":"We will build twelve useful expressions. For each one, listen to the expression, understand the meaning, and hear an example. Use the pause after each example to repeat or create a similar sentence.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":52.854,"end":66.746},{"lang":"en-US","text":"budget.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":67.246,"end":68.605},{"lang":"en-US","text":"A plan for how much money can be used.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":68.905,"end":71.939},{"lang":"en-US","text":"The pilot budget is still a draft.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":72.439,"end":75.138},{"lang":"en-US","text":"cash flow.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":76.838,"end":78.378},{"lang":"en-US","text":"Money coming into and going out of an operation over time.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":78.678,"end":82.532},{"lang":"en-US","text":"The cash flow forecast tracks money coming in and going out.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":83.032,"end":87.165},{"lang":"en-US","text":"revenue.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":88.865,"end":90.19},{"lang":"en-US","text":"Income generated by the business activity in this example.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":90.49,"end":94.533},{"lang":"en-US","text":"Pilot revenue was twenty thousand dollars.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":95.033,"end":98.282},{"lang":"en-US","text":"profit.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":99.982,"end":101.486},{"lang":"en-US","text":"The amount left after the recorded costs in this example.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":101.786,"end":105.61},{"lang":"en-US","text":"Pilot profit was three thousand dollars after recorded costs.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":106.11,"end":110.569},{"lang":"en-US","text":"KPI.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":112.269,"end":113.713},{"lang":"en-US","text":"A selected measure used to check performance against a goal.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":114.013,"end":117.857},{"lang":"en-US","text":"Our KPI is the percentage of orders delivered on time.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":118.357,"end":122.331},{"lang":"en-US","text":"workflow.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":124.031,"end":125.56},{"lang":"en-US","text":"The sequence of steps used to complete work.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":125.86,"end":129.049},{"lang":"en-US","text":"The workflow has an approval step.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":129.549,"end":132.163},{"lang":"en-US","text":"spreadsheet.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":133.863,"end":135.547},{"lang":"en-US","text":"A document that organizes data in rows and columns.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":135.847,"end":139.761},{"lang":"en-US","text":"The spreadsheet separates results from estimates.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":140.261,"end":143.73},{"lang":"en-US","text":"outsource.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":145.43,"end":147.059},{"lang":"en-US","text":"Ask an outside provider to perform a task.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":147.359,"end":150.748},{"lang":"en-US","text":"We may outsource a small support task.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":151.248,"end":154.432},{"lang":"en-US","text":"B2B.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":156.132,"end":157.581},{"lang":"en-US","text":"Business to business: selling to another company.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":157.881,"end":161.555},{"lang":"en-US","text":"The B2B service is sold to other companies.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":162.055,"end":165.389},{"lang":"en-US","text":"B2C.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":167.089,"end":168.624},{"lang":"en-US","text":"Business to consumer: selling to an individual customer.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":168.924,"end":173.173},{"lang":"en-US","text":"The B2C service is sold directly to individual customers.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":173.673,"end":178.076},{"lang":"en-US","text":"asset.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":179.776,"end":181.185},{"lang":"en-US","text":"A resource with value that an organization uses or controls.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":181.485,"end":185.729},{"lang":"en-US","text":"The server is an asset used by the team.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":186.229,"end":189.198},{"lang":"en-US","text":"target.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":190.898,"end":192.322},{"lang":"en-US","text":"The level of performance the team wants to reach.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":192.622,"end":195.906},{"lang":"en-US","text":"The target is ninety-five percent on-time delivery.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":196.406,"end":200.015}],"start":52.854,"end":201.715},{"id":"pronunciation","title":"Pronunciation and repetition","segments":[{"lang":"en-US","text":"Now focus on pronunciation. The examples are spoken models, not a pronunciation score. Listen for the stronger beat and how words join in a phrase. Repeat slowly, then say the whole phrase naturally.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":201.715,"end":216.807},{"lang":"en-US","text":"The strongest beat is at the beginning of budget. Listen to the ending. Do not add an extra vowel after the final consonant.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":217.307,"end":225.915},{"lang":"en-US","text":"budget.","pauseMs":1800,"rate":78,"role":"narrator","pitch":0,"start":226.415,"end":227.774},{"lang":"en-US","text":"budget.","pauseMs":1800,"rate":98,"role":"narrator","pitch":0,"start":229.574,"end":230.934},{"lang":"en-US","text":"Both revenue and profit have a strong first beat. Keep the two measures separate when you explain the figures. Listen, pause, and say the complete group.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":232.734,"end":243.892},{"lang":"en-US","text":"revenue and profit.","pauseMs":1800,"rate":78,"role":"narrator","pitch":0,"start":244.392,"end":246.391},{"lang":"en-US","text":"revenue and profit.","pauseMs":1800,"rate":98,"role":"narrator","pitch":0,"start":248.191,"end":250.19},{"lang":"en-US","text":"Say the letters individually. Then explain the measure in ordinary words. A clear explanation matters more than using an abbreviation.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":251.99,"end":261.448},{"lang":"en-US","text":"K. P. I..","pauseMs":1800,"rate":78,"role":"narrator","pitch":0,"start":261.948,"end":263.517},{"lang":"en-US","text":"K. P. I..","pauseMs":1800,"rate":98,"role":"narrator","pitch":0,"start":265.317,"end":266.887},{"lang":"en-US","text":"K. P. I. Business to business. Business to consumer.","pauseMs":1800,"rate":94,"role":"narrator","pitch":0,"start":268.687,"end":273.385}],"start":201.715,"end":275.185},{"id":"dialogue","title":"Workplace dialogue","segments":[{"lang":"en-US","text":"Listen to the complete conversation. Notice the request, the clarification and the final commitment. The two roles keep the same delivery throughout. Read the transcript afterwards if you need support.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":275.185,"end":289.002},{"lang":"en-US","text":"Let us review the pilot budget. It is still a draft, so no new spending is approved.","pauseMs":400,"rate":94,"role":"Dana","pitch":-1,"start":289.502,"end":296.131},{"lang":"en-US","text":"The spreadsheet separates last month’s results from next month’s estimates.","pauseMs":400,"rate":90,"role":"Sam","pitch":2,"start":296.531,"end":301.384},{"lang":"en-US","text":"What revenue did the pilot generate last month?","pauseMs":400,"rate":94,"role":"Dana","pitch":-1,"start":301.784,"end":305.188},{"lang":"en-US","text":"Revenue was twenty thousand dollars, and profit was three thousand after recorded costs.","pauseMs":400,"rate":90,"role":"Sam","pitch":2,"start":305.588,"end":311.732},{"lang":"en-US","text":"That does not tell us when customers pay. What does the cash flow forecast show?","pauseMs":400,"rate":94,"role":"Dana","pitch":-1,"start":312.132,"end":318.075},{"lang":"en-US","text":"Some payments are expected next month. The cash flow forecast keeps that timing visible.","pauseMs":400,"rate":90,"role":"Sam","pitch":2,"start":318.475,"end":325.134},{"lang":"en-US","text":"Our delivery KPI was ninety percent on time. The target is ninety-five percent.","pauseMs":400,"rate":94,"role":"Dana","pitch":-1,"start":325.534,"end":331.972},{"lang":"en-US","text":"The workflow has a long approval step. We may outsource one small support task as a test.","pauseMs":400,"rate":90,"role":"Sam","pitch":2,"start":332.372,"end":339.115},{"lang":"en-US","text":"Is this for our B2B service, which sells to other companies?","pauseMs":400,"rate":94,"role":"Dana","pitch":-1,"start":339.515,"end":344.114},{"lang":"en-US","text":"Yes. The B2C service for individual customers is outside this pilot.","pauseMs":400,"rate":90,"role":"Sam","pitch":2,"start":344.514,"end":350.492},{"lang":"en-US","text":"The existing server is an asset we can use. Please check the test cost before proposing a purchase.","pauseMs":400,"rate":94,"role":"Dana","pitch":-1,"start":350.892,"end":357.951},{"lang":"en-US","text":"I will send the draft on Thursday, including the KPI, target and approval request.","pauseMs":400,"rate":90,"role":"Sam","pitch":2,"start":358.351,"end":364.459},{"lang":"en-US","text":"Listen again later and take one role. Pause before that person speaks and predict the response. A different answer can still be appropriate if it communicates the same goal clearly.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":364.859,"end":376.691}],"start":275.185,"end":377.191},{"id":"practice","title":"Your turn to respond","segments":[{"lang":"en-US","text":"Your turn. You will hear four prompts. After each prompt there is a short pause for your response, followed by one possible model. Pause the player if you need more time. The model is not the only correct answer.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":377.191,"end":392.928},{"lang":"en-US","text":"Are revenue and profit the same here?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"start":393.428,"end":396.227},{"lang":"en-US","text":"One possible response is:","pauseMs":200,"rate":94,"role":"narrator","pitch":0,"start":400.727,"end":403.251},{"lang":"en-US","text":"No. Revenue was twenty thousand dollars, while profit was three thousand after recorded costs.","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"start":403.451,"end":410.89},{"lang":"en-US","text":"What does our KPI measure?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"start":412.49,"end":414.954},{"lang":"en-US","text":"One possible response is:","pauseMs":200,"rate":94,"role":"narrator","pitch":0,"start":419.454,"end":421.978},{"lang":"en-US","text":"It measures the percentage of orders delivered on time. The target is ninety-five percent.","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"start":422.178,"end":428.476},{"lang":"en-US","text":"What change are you proposing?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"start":430.076,"end":432.435},{"lang":"en-US","text":"One possible response is:","pauseMs":200,"rate":94,"role":"narrator","pitch":0,"start":436.935,"end":439.459},{"lang":"en-US","text":"We may outsource a small support task to test a shorter workflow.","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"start":439.659,"end":444.228},{"lang":"en-US","text":"What will you do next?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"start":445.828,"end":447.857},{"lang":"en-US","text":"One possible response is:","pauseMs":200,"rate":94,"role":"narrator","pitch":0,"start":452.357,"end":454.881},{"lang":"en-US","text":"I will send the draft and request approval on Thursday.","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"start":455.081,"end":458.73}],"start":377.191,"end":460.33},{"id":"summary","title":"Recap and application","segments":[{"lang":"en-US","text":"To recap, choose three expressions from the episode and use them in a short message. Check the goal, the person responsible and the next step. Keep observed facts separate from predictions. Return to the lesson for the games, grammar practice and final review.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":460.33,"end":478.206},{"lang":"en-US","text":"This is a practice activity. Listening and self-assessment do not certify pronunciation or proficiency. Ask your teacher for feedback and repeat one chapter with a specific improvement in mind. Thank you for studying with I S M Business.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":478.706,"end":494.887}],"start":460.33,"end":495.387}],"audio":"assets/podcasts/budget-and-workflow-en.mp3","duration":495.387,"bytes":3963967,"sha256":"9df26646e23ffdcfde90be587c66d90c27a8a951eadf81066e0d3e17262dc1cc"}},"disclosure":"Narração sintetizada: Microsoft Maria (português) e Microsoft Zira (inglês). Os personagens compartilham a voz inglesa com variações de ritmo e tom."},{"id":"supplier-delivery-agreement","title":"Fornecedores: confirmar preço, documentos e entrega","lesson":"business-practice.html#supplier-delivery-agreement/0","image":"assets/reference-supplier-delivery.svg","versions":{"pt":{"label":"Português + exemplos em inglês","chapters":[{"id":"opening","title":"Comece pelo contexto","segments":[{"lang":"pt-BR","text":"Bem-vindo a uma aula em áudio do ISM Business. Este episódio usa situações profissionais fictícias. Na primeira vez, acompanhe o sentido. Depois retorne aos capítulos e pratique em voz alta. Pause sempre que precisar de mais tempo. A narração é sintetizada. Os personagens usam uma voz inglesa com pequenas variações de ritmo e tom.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":0.0,"end":32.656},{"lang":"pt-BR","text":"Conheça a situação que vamos praticar.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":33.156,"end":37.22},{"lang":"en-US","text":"Your fictional team needs sample units for a distributor. A supplier has sent a quotation, but freight and the delivery estimate need clarification before an order is approved.","pauseMs":1300,"rate":92,"role":"narrator","pitch":0,"start":37.72,"end":48.692},{"lang":"pt-BR","text":"Ao final, explique uma expressão útil, participe da conversa e deixe claro um próximo passo. Você não precisa decorar todas as frases. O objetivo é comunicar a mensagem com suas próprias palavras.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":49.992,"end":69.014}],"start":0.0,"end":69.514},{"id":"vocabulary","title":"Vocabulário explicado","segments":[{"lang":"pt-BR","text":"Vamos trabalhar doze expressões úteis. Para cada uma, ouça o termo, compreenda o sentido e acompanhe uma frase de exemplo. Use a pausa depois do exemplo para repetir ou criar uma frase semelhante.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":69.514,"end":88.03},{"lang":"en-US","text":"supply chain.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":88.53,"end":90.339},{"lang":"pt-BR","text":"cadeia de suprimentos.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":90.639,"end":93.479},{"lang":"en-US","text":"Our supply chain includes two suppliers and a carrier.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":93.979,"end":97.853},{"lang":"en-US","text":"supplier.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":99.553,"end":101.107},{"lang":"pt-BR","text":"fornecedor.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":101.407,"end":103.55},{"lang":"en-US","text":"The supplier has sent a quotation.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":104.05,"end":106.803},{"lang":"en-US","text":"quotation.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":108.503,"end":110.278},{"lang":"pt-BR","text":"cotação comercial.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":110.578,"end":113.168},{"lang":"en-US","text":"The quotation does not include freight.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":113.668,"end":116.687},{"lang":"en-US","text":"invoice.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":118.387,"end":119.996},{"lang":"pt-BR","text":"fatura.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":120.296,"end":122.007},{"lang":"en-US","text":"The invoice must show the agreed order details.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":122.507,"end":125.906},{"lang":"en-US","text":"freight.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":127.606,"end":129.006},{"lang":"pt-BR","text":"frete; transporte de carga.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":129.306,"end":133.008},{"lang":"en-US","text":"Freight will be listed separately.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":133.508,"end":135.927},{"lang":"en-US","text":"shipment.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":137.627,"end":139.131},{"lang":"pt-BR","text":"remessa.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":139.431,"end":141.205},{"lang":"en-US","text":"The shipment will contain sample units.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":141.705,"end":144.619},{"lang":"en-US","text":"lead time.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":146.319,"end":147.813},{"lang":"pt-BR","text":"prazo entre o pedido confirmado e a entrega neste cenário.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":148.113,"end":153.659},{"lang":"en-US","text":"The lead time estimate is ten working days after order confirmation.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":154.159,"end":158.678},{"lang":"en-US","text":"purchase order.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":160.378,"end":162.097},{"lang":"pt-BR","text":"pedido de compra.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":162.397,"end":164.827},{"lang":"en-US","text":"The purchase order requires internal approval.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":165.327,"end":168.646},{"lang":"en-US","text":"stakeholder.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":170.346,"end":172.08},{"lang":"pt-BR","text":"parte interessada.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":172.38,"end":174.921},{"lang":"en-US","text":"Each stakeholder needs the confirmed delivery information.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":175.421,"end":179.285},{"lang":"en-US","text":"procurement.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":180.985,"end":182.639},{"lang":"pt-BR","text":"área ou processo de compras.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":182.939,"end":186.192},{"lang":"en-US","text":"Procurement will review the quotation.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":186.692,"end":189.516},{"lang":"en-US","text":"win-win.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":191.216,"end":192.716},{"lang":"pt-BR","text":"vantajoso para ambas as partes.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":193.016,"end":196.65},{"lang":"en-US","text":"A smaller sample order could be a win-win solution.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":197.15,"end":200.604},{"lang":"en-US","text":"close a deal.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":202.304,"end":203.918},{"lang":"pt-BR","text":"fechar um negócio.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":204.218,"end":206.692},{"lang":"en-US","text":"We cannot close a deal before approval.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":207.192,"end":210.106}],"start":69.514,"end":211.806},{"id":"pronunciation","title":"Pronúncia e repetição","segments":[{"lang":"pt-BR","text":"Agora vamos observar a pronúncia. Os exemplos são modelos falados, não uma avaliação da sua fala. Ouça a parte mais forte e como as palavras se ligam. Repita com calma e depois diga a expressão como um grupo.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":211.806,"end":231.741},{"lang":"pt-BR","text":"Ouça a semelhança com as palavras inglesas que significam atrasado e esperar. As letras G e H não têm som próprio nesta palavra. Escute o modelo e repita.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":232.241,"end":247.514},{"lang":"en-US","text":"freight.","pauseMs":1800,"rate":78,"role":"narrator","pitch":0,"start":248.014,"end":249.414},{"lang":"en-US","text":"freight.","pauseMs":1800,"rate":98,"role":"narrator","pitch":0,"start":251.214,"end":252.613},{"lang":"pt-BR","text":"A palavra para cotação tem destaque no meio. A palavra para fatura tem destaque no início. Ouça o contraste e diferencie também a função dos documentos.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":254.413,"end":268.906},{"lang":"en-US","text":"quotation and invoice.","pauseMs":1800,"rate":78,"role":"narrator","pitch":0,"start":269.406,"end":271.735},{"lang":"en-US","text":"quotation and invoice.","pauseMs":1800,"rate":98,"role":"narrator","pitch":0,"start":273.535,"end":275.864},{"lang":"pt-BR","text":"A parte mais forte fica no meio da palavra. Comece de modo leve e torne o trecho central mais claro. Depois use a palavra em uma frase completa.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":277.664,"end":292.281},{"lang":"en-US","text":"procurement.","pauseMs":1800,"rate":78,"role":"narrator","pitch":0,"start":292.781,"end":294.435},{"lang":"en-US","text":"procurement.","pauseMs":1800,"rate":98,"role":"narrator","pitch":0,"start":296.235,"end":297.89},{"lang":"en-US","text":"Freight. Late. Wait. Procurement will review the quotation.","pauseMs":1800,"rate":94,"role":"narrator","pitch":0,"start":299.69,"end":306.433}],"start":211.806,"end":308.233},{"id":"dialogue","title":"Diálogo profissional","segments":[{"lang":"pt-BR","text":"Ouça a conversa completa. Observe o pedido, o esclarecimento e o compromisso final. Cada papel mantém o mesmo padrão de voz durante o diálogo. Depois, consulte a transcrição se precisar de apoio.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":308.233,"end":327.836},{"lang":"en-US","text":"Our supply chain review shows a delay in one component. Can we discuss the sample order?","pauseMs":400,"rate":94,"role":"Elliot","pitch":-1,"start":328.336,"end":334.679},{"lang":"en-US","text":"Yes. Is the supplier able to provide twenty sample units?","pauseMs":400,"rate":90,"role":"Noor","pitch":2,"start":335.079,"end":340.178},{"lang":"en-US","text":"The quotation covers twenty units, but it does not include freight.","pauseMs":400,"rate":94,"role":"Elliot","pitch":-1,"start":340.578,"end":345.477},{"lang":"en-US","text":"Please list freight separately so procurement can compare the total cost.","pauseMs":400,"rate":90,"role":"Noor","pitch":2,"start":345.877,"end":350.59},{"lang":"en-US","text":"The estimated lead time is ten working days after order confirmation. It is not yet a guaranteed date.","pauseMs":400,"rate":94,"role":"Elliot","pitch":-1,"start":350.99,"end":358.228},{"lang":"en-US","text":"Understood. We cannot send the purchase order before internal approval.","pauseMs":400,"rate":90,"role":"Noor","pitch":2,"start":358.628,"end":364.092},{"lang":"en-US","text":"Once the order is confirmed, the shipment will contain only the sample units.","pauseMs":400,"rate":94,"role":"Elliot","pitch":-1,"start":364.492,"end":369.78},{"lang":"en-US","text":"Please make sure the invoice shows the agreed unit price and the separate freight charge.","pauseMs":400,"rate":90,"role":"Noor","pitch":2,"start":370.18,"end":375.314},{"lang":"en-US","text":"I will send the revised quotation tomorrow. Which stakeholder should receive the delivery update?","pauseMs":400,"rate":94,"role":"Elliot","pitch":-1,"start":375.714,"end":382.302},{"lang":"en-US","text":"Our procurement contact should receive it. A small sample order could be a win-win solution before a larger commitment.","pauseMs":400,"rate":90,"role":"Noor","pitch":2,"start":382.702,"end":390.45},{"lang":"en-US","text":"That makes sense. We can close a deal only after the price and approval are confirmed.","pauseMs":400,"rate":94,"role":"Elliot","pitch":-1,"start":390.85,"end":396.943},{"lang":"en-US","text":"Agreed. Send the price, freight and delivery estimate in writing tomorrow, and procurement will review them.","pauseMs":400,"rate":90,"role":"Noor","pitch":2,"start":397.343,"end":405.172},{"lang":"pt-BR","text":"Em outra escuta, assuma um dos papéis. Pause antes da fala desse personagem e tente responder. Uma resposta diferente também pode ser adequada quando comunica o mesmo objetivo com clareza.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":405.572,"end":423.402}],"start":308.233,"end":423.902},{"id":"practice","title":"Sua vez de responder","segments":[{"lang":"pt-BR","text":"Agora é sua vez. Você ouvirá quatro perguntas. Depois de cada uma haverá uma pausa curta para responder e, em seguida, um modelo possível. Pause o player se precisar de mais tempo. O modelo não é a única resposta correta.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":423.902,"end":446.214},{"lang":"en-US","text":"Does your quotation include every cost?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"start":446.714,"end":449.823},{"lang":"pt-BR","text":"Uma resposta possível é:","pauseMs":200,"rate":98,"role":"narrator","pitch":0,"start":454.323,"end":457.383},{"lang":"en-US","text":"Could you confirm whether freight is included and list it separately?","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"start":457.583,"end":461.582},{"lang":"en-US","text":"Can you guarantee delivery in ten days?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"start":463.182,"end":466.166},{"lang":"pt-BR","text":"Uma resposta possível é:","pauseMs":200,"rate":98,"role":"narrator","pitch":0,"start":470.666,"end":473.726},{"lang":"en-US","text":"The current estimate is ten working days after order confirmation; I cannot guarantee a date yet.","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"start":473.926,"end":480.284},{"lang":"en-US","text":"Can we send the purchase order now?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"start":481.884,"end":484.508},{"lang":"pt-BR","text":"Uma resposta possível é:","pauseMs":200,"rate":98,"role":"narrator","pitch":0,"start":489.008,"end":492.068},{"lang":"en-US","text":"Not yet. Procurement must review the revised quotation and approve the order first.","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"start":492.268,"end":498.521},{"lang":"en-US","text":"What should we confirm tomorrow?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"start":500.121,"end":502.585},{"lang":"pt-BR","text":"Uma resposta possível é:","pauseMs":200,"rate":98,"role":"narrator","pitch":0,"start":507.085,"end":510.145},{"lang":"en-US","text":"Please confirm the price, freight and delivery estimate in writing tomorrow.","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"start":510.345,"end":515.244}],"start":423.902,"end":516.844},{"id":"summary","title":"Resumo e aplicação","segments":[{"lang":"pt-BR","text":"Para concluir, escolha três expressões do episódio e use-as em uma mensagem curta. Confira o objetivo, o responsável e o próximo passo. Separe fatos observados de previsões. Volte à aula para fazer os jogos, os exercícios de gramática e a revisão.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":516.844,"end":541.407},{"lang":"pt-BR","text":"Esta é uma atividade de prática. A escuta e a autoavaliação não certificam pronúncia ou proficiência. Peça feedback ao professor e repita um capítulo buscando uma melhoria específica. Obrigado por estudar com o ISM Business.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"start":541.907,"end":563.262}],"start":516.844,"end":563.762}],"audio":"assets/podcasts/supplier-delivery-agreement-pt.mp3","duration":563.762,"bytes":4510867,"sha256":"ed5f41a56d7060f10a9abbdb44c21e1166da02a84c0b32fae687b2c3eb82b6a9"},"en":{"label":"English only","chapters":[{"id":"opening","title":"Start with the situation","segments":[{"lang":"en-US","text":"Welcome to an I S M Business audio lesson. This episode uses fictional workplace situations. Listen once for meaning, then return to a chapter and practise aloud. You can pause whenever you need more thinking time. This is synthetic narration, with a single English voice using small delivery variations for the two dialogue roles.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":0.0,"end":22.605},{"lang":"en-US","text":"Here is your situation.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":23.105,"end":25.32},{"lang":"en-US","text":"Your fictional team needs sample units for a distributor. A supplier has sent a quotation, but freight and the delivery estimate need clarification before an order is approved.","pauseMs":1300,"rate":92,"role":"narrator","pitch":0,"start":25.82,"end":36.792},{"lang":"en-US","text":"At the end, explain one useful expression, take part in the conversation, and make a clear next step. You do not need to memorize every sentence. Aim to communicate the message in your own words.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":38.092,"end":52.119}],"start":0.0,"end":52.619},{"id":"vocabulary","title":"Vocabulary explained","segments":[{"lang":"en-US","text":"We will build twelve useful expressions. For each one, listen to the expression, understand the meaning, and hear an example. Use the pause after each example to repeat or create a similar sentence.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":52.619,"end":66.511},{"lang":"en-US","text":"supply chain.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":67.011,"end":68.82},{"lang":"en-US","text":"The connected organizations and processes that move goods to customers.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":69.12,"end":73.824},{"lang":"en-US","text":"Our supply chain includes two suppliers and a carrier.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":74.324,"end":78.198},{"lang":"en-US","text":"supplier.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":79.898,"end":81.452},{"lang":"en-US","text":"A person or company providing goods or services.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":81.752,"end":85.47},{"lang":"en-US","text":"The supplier has sent a quotation.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":85.97,"end":88.724},{"lang":"en-US","text":"quotation.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":90.424,"end":92.199},{"lang":"en-US","text":"A statement of proposed prices and conditions.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":92.499,"end":96.023},{"lang":"en-US","text":"The quotation does not include freight.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":96.523,"end":99.542},{"lang":"en-US","text":"invoice.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":101.242,"end":102.851},{"lang":"en-US","text":"A document requesting payment for an agreed transaction.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":103.151,"end":107.05},{"lang":"en-US","text":"The invoice must show the agreed order details.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":107.55,"end":110.949},{"lang":"en-US","text":"freight.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":112.649,"end":114.048},{"lang":"en-US","text":"The transportation of goods, or its charge in this example.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":114.348,"end":118.747},{"lang":"en-US","text":"Freight will be listed separately.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":119.247,"end":121.666},{"lang":"en-US","text":"shipment.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":123.366,"end":124.87},{"lang":"en-US","text":"A group of goods being transported.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":125.17,"end":127.964},{"lang":"en-US","text":"The shipment will contain sample units.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":128.464,"end":131.378},{"lang":"en-US","text":"lead time.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":133.078,"end":134.573},{"lang":"en-US","text":"In this scenario, the estimated period from order confirmation to delivery.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":134.873,"end":140.161},{"lang":"en-US","text":"The lead time estimate is ten working days after order confirmation.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":140.661,"end":145.18},{"lang":"en-US","text":"purchase order.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":146.88,"end":148.599},{"lang":"en-US","text":"A document through which a buyer places an order.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":148.899,"end":152.233},{"lang":"en-US","text":"The purchase order requires internal approval.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":152.733,"end":156.052},{"lang":"en-US","text":"stakeholder.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":157.752,"end":159.486},{"lang":"en-US","text":"A person or group affected by an activity or its result.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":159.786,"end":163.91},{"lang":"en-US","text":"Each stakeholder needs the confirmed delivery information.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":164.41,"end":168.273},{"lang":"en-US","text":"procurement.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":169.973,"end":171.628},{"lang":"en-US","text":"The purchasing process or the team responsible for it.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":171.928,"end":175.576},{"lang":"en-US","text":"Procurement will review the quotation.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":176.076,"end":178.9},{"lang":"en-US","text":"win-win.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":180.6,"end":182.1},{"lang":"en-US","text":"An option intended to benefit both sides.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":182.4,"end":185.524},{"lang":"en-US","text":"A smaller sample order could be a win-win solution.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":186.024,"end":189.477},{"lang":"en-US","text":"close a deal.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"start":191.177,"end":192.792},{"lang":"en-US","text":"Reach a commercial agreement, subject to the required approvals.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":193.092,"end":197.695},{"lang":"en-US","text":"We cannot close a deal before approval.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"start":198.195,"end":201.109}],"start":52.619,"end":202.809},{"id":"pronunciation","title":"Pronunciation and repetition","segments":[{"lang":"en-US","text":"Now focus on pronunciation. The examples are spoken models, not a pronunciation score. Listen for the stronger beat and how words join in a phrase. Repeat slowly, then say the whole phrase naturally.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":202.809,"end":217.901},{"lang":"en-US","text":"Freight rhymes with late and wait. The letters G and H are not pronounced here. Listen to freight, late, wait, then repeat freight.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":218.401,"end":228.589},{"lang":"en-US","text":"freight.","pauseMs":1800,"rate":78,"role":"narrator","pitch":0,"start":229.089,"end":230.489},{"lang":"en-US","text":"freight.","pauseMs":1800,"rate":98,"role":"narrator","pitch":0,"start":232.289,"end":233.688},{"lang":"en-US","text":"Quotation has its strongest beat in the middle. Invoice has a strong first beat. Listen to the contrast and keep the document meanings separate.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":235.488,"end":245.326},{"lang":"en-US","text":"quotation and invoice.","pauseMs":1800,"rate":78,"role":"narrator","pitch":0,"start":245.826,"end":248.155},{"lang":"en-US","text":"quotation and invoice.","pauseMs":1800,"rate":98,"role":"narrator","pitch":0,"start":249.955,"end":252.284},{"lang":"en-US","text":"The strongest beat is in the middle of procurement. Start gently and make the middle easy to hear. Then use the word inside a complete sentence.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":254.084,"end":263.727},{"lang":"en-US","text":"procurement.","pauseMs":1800,"rate":78,"role":"narrator","pitch":0,"start":264.227,"end":265.881},{"lang":"en-US","text":"procurement.","pauseMs":1800,"rate":98,"role":"narrator","pitch":0,"start":267.681,"end":269.336},{"lang":"en-US","text":"Freight. Late. Wait. Procurement will review the quotation.","pauseMs":1800,"rate":94,"role":"narrator","pitch":0,"start":271.136,"end":277.879}],"start":202.809,"end":279.679},{"id":"dialogue","title":"Workplace dialogue","segments":[{"lang":"en-US","text":"Listen to the complete conversation. Notice the request, the clarification and the final commitment. The two roles keep the same delivery throughout. Read the transcript afterwards if you need support.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":279.679,"end":293.496},{"lang":"en-US","text":"Our supply chain review shows a delay in one component. Can we discuss the sample order?","pauseMs":400,"rate":94,"role":"Elliot","pitch":-1,"start":293.996,"end":300.34},{"lang":"en-US","text":"Yes. Is the supplier able to provide twenty sample units?","pauseMs":400,"rate":90,"role":"Noor","pitch":2,"start":300.74,"end":305.838},{"lang":"en-US","text":"The quotation covers twenty units, but it does not include freight.","pauseMs":400,"rate":94,"role":"Elliot","pitch":-1,"start":306.238,"end":311.137},{"lang":"en-US","text":"Please list freight separately so procurement can compare the total cost.","pauseMs":400,"rate":90,"role":"Noor","pitch":2,"start":311.537,"end":316.251},{"lang":"en-US","text":"The estimated lead time is ten working days after order confirmation. It is not yet a guaranteed date.","pauseMs":400,"rate":94,"role":"Elliot","pitch":-1,"start":316.651,"end":323.889},{"lang":"en-US","text":"Understood. We cannot send the purchase order before internal approval.","pauseMs":400,"rate":90,"role":"Noor","pitch":2,"start":324.289,"end":329.752},{"lang":"en-US","text":"Once the order is confirmed, the shipment will contain only the sample units.","pauseMs":400,"rate":94,"role":"Elliot","pitch":-1,"start":330.152,"end":335.441},{"lang":"en-US","text":"Please make sure the invoice shows the agreed unit price and the separate freight charge.","pauseMs":400,"rate":90,"role":"Noor","pitch":2,"start":335.841,"end":340.974},{"lang":"en-US","text":"I will send the revised quotation tomorrow. Which stakeholder should receive the delivery update?","pauseMs":400,"rate":94,"role":"Elliot","pitch":-1,"start":341.374,"end":347.962},{"lang":"en-US","text":"Our procurement contact should receive it. A small sample order could be a win-win solution before a larger commitment.","pauseMs":400,"rate":90,"role":"Noor","pitch":2,"start":348.362,"end":356.11},{"lang":"en-US","text":"That makes sense. We can close a deal only after the price and approval are confirmed.","pauseMs":400,"rate":94,"role":"Elliot","pitch":-1,"start":356.51,"end":362.604},{"lang":"en-US","text":"Agreed. Send the price, freight and delivery estimate in writing tomorrow, and procurement will review them.","pauseMs":400,"rate":90,"role":"Noor","pitch":2,"start":363.004,"end":370.832},{"lang":"en-US","text":"Listen again later and take one role. Pause before that person speaks and predict the response. A different answer can still be appropriate if it communicates the same goal clearly.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":371.232,"end":383.064}],"start":279.679,"end":383.564},{"id":"practice","title":"Your turn to respond","segments":[{"lang":"en-US","text":"Your turn. You will hear four prompts. After each prompt there is a short pause for your response, followed by one possible model. Pause the player if you need more time. The model is not the only correct answer.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":383.564,"end":399.301},{"lang":"en-US","text":"Does your quotation include every cost?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"start":399.801,"end":402.91},{"lang":"en-US","text":"One possible response is:","pauseMs":200,"rate":94,"role":"narrator","pitch":0,"start":407.41,"end":409.934},{"lang":"en-US","text":"Could you confirm whether freight is included and list it separately?","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"start":410.134,"end":414.132},{"lang":"en-US","text":"Can you guarantee delivery in ten days?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"start":415.732,"end":418.716},{"lang":"en-US","text":"One possible response is:","pauseMs":200,"rate":94,"role":"narrator","pitch":0,"start":423.216,"end":425.741},{"lang":"en-US","text":"The current estimate is ten working days after order confirmation; I cannot guarantee a date yet.","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"start":425.941,"end":432.299},{"lang":"en-US","text":"Can we send the purchase order now?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"start":433.899,"end":436.523},{"lang":"en-US","text":"One possible response is:","pauseMs":200,"rate":94,"role":"narrator","pitch":0,"start":441.023,"end":443.547},{"lang":"en-US","text":"Not yet. Procurement must review the revised quotation and approve the order first.","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"start":443.747,"end":450.0},{"lang":"en-US","text":"What should we confirm tomorrow?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"start":451.6,"end":454.064},{"lang":"en-US","text":"One possible response is:","pauseMs":200,"rate":94,"role":"narrator","pitch":0,"start":458.564,"end":461.088},{"lang":"en-US","text":"Please confirm the price, freight and delivery estimate in writing tomorrow.","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"start":461.288,"end":466.187}],"start":383.564,"end":467.787},{"id":"summary","title":"Recap and application","segments":[{"lang":"en-US","text":"To recap, choose three expressions from the episode and use them in a short message. Check the goal, the person responsible and the next step. Keep observed facts separate from predictions. Return to the lesson for the games, grammar practice and final review.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":467.787,"end":485.663},{"lang":"en-US","text":"This is a practice activity. Listening and self-assessment do not certify pronunciation or proficiency. Ask your teacher for feedback and repeat one chapter with a specific improvement in mind. Thank you for studying with I S M Business.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"start":486.163,"end":502.344}],"start":467.787,"end":502.844}],"audio":"assets/podcasts/supplier-delivery-agreement-en.mp3","duration":502.844,"bytes":4023527,"sha256":"1c153e3f280544e7314a9e826889bee35d74738d8dc40d871e5261487f61e2a0"}},"disclosure":"Narração sintetizada: Microsoft Maria (português) e Microsoft Zira (inglês). Os personagens compartilham a voz inglesa com variações de ritmo e tom."}];
